import { extension, isError as isCoreError, operation, parse } from "@tinker/core";
import { z } from "zod";

import type { Errors } from "~/components/errors";

import { sdkServerModule, sdkTransportModule, sdkTypesModule } from "./modules";
import { mcpServer, mcpTools } from "./tools.server";
import type { McpReply } from "./tools.server";

/** How one tool call ended: its reply, Core's cancel, or the reason the reply gives. */
type ToolEnd =
  | { status: "success"; value: McpReply }
  | { status: "cancelled"; reason: unknown }
  | { status: "notDone"; why: string };

const toolCall = z.object({ name: z.string(), arguments: z.unknown() });

/** A managed refusal a tool raised: its message is the reply's reason. */
const refused = z.object({
  kind: z.literal("Refused" satisfies Errors.Name),
  payload: z.object({ message: z.string() }),
});

/**
 * One tool call. An operation body cannot run an operation it picks at run time, so the
 * `mcpRuns` extension answers this call: it runs the tool in the caller's layer, with the
 * caller's tags, and says how the run ended. Without the extension this body says so.
 */
const callTool = operation({
  label: "mcp.tool",
  input: toolCall,
  run: async (_deps, { raise: coreRaise }): Promise<ToolEnd> => {
    const raise: Errors.Raise = coreRaise;

    return raise("McpNotInstalled", {});
  },
});

/**
 * Runs each `mcp.tool` call as one Core run of the tool's operation. The raw `arguments` go in
 * as `rawInput`, so the operation's own input parse is the only parse. A managed `Refused` and
 * bad input become the reply's reason; any other failure is logged once and hides its detail.
 * Startup checks the server and tool tags before ready.
 */
export const mcpRuns = extension({
  label: "mcp.runs",
  hooks: {
    async start({ resolve, next }) {
      resolve(mcpServer);
      resolve(mcpTools);
      await next();
    },
    run(event) {
      if (event.op !== callTool) return event.next();

      const call = parse(toolCall, event.call?.input);
      const tool = event.resolve(mcpTools).find((entry) => entry.name === call.name);
      if (tool === undefined) return { status: "notDone", why: `there is no tool "${call.name}".` };

      const settled = event.settle(tool.run, { rawInput: call.arguments, signal: event.signal });

      return Promise.resolve(settled).then((result): ToolEnd => {
        if (result.status !== "failed") return result;

        const { error } = result;
        const refusal = refused.safeParse(error);
        if (refusal.success) return { status: "notDone", why: refusal.data.payload.message };

        const cause = isCoreError(error, "DataValidationFailed") ? error.payload : undefined;
        if (cause?.label === tool.run.label && isCoreError(cause.cause, "SchemaRejected")) {
          const issues = cause.cause.payload.issues.map(({ path = [], message }) => {
            const field = path.map((key) => String(typeof key === "object" ? key.key : key));

            return `${field.join(".") || "arguments"}: ${message}`;
          });

          return { status: "notDone", why: issues.join("; ") };
        }

        event.log.error("mcp tool failed", { tool: call.name, error });

        return { status: "notDone", why: "the tool failed." };
      });
    },
  },
});

/**
 * ADR 0103's named protocol exception, as `handleAuth`: the MCP SDK owns the Streamable HTTP
 * contract, so this operation hands it the whole request and returns its reply. The app has
 * already checked the caller and bound the caller's tags on this call. Stateless, as obelisk:
 * a new SDK server and transport per request, both closed when the reply is done.
 */
export const handleMcp = operation({
  label: "handleMcp",
  input: z.instanceof(Request),
  depends: {
    info: mcpServer,
    tools: mcpTools,
    callTool,
    sdk: sdkServerModule,
    web: sdkTransportModule,
    types: sdkTypesModule,
  },
  run: async ({ info, tools, callTool, sdk, web, types }, { input, signal }) => {
    if (input.method !== "POST") {
      return new Response(null, { status: 405, headers: { allow: "POST" } });
    }

    signal.throwIfAborted();

    const server = new sdk.Server(
      { name: info.name, version: info.version },
      { capabilities: { tools: {} }, instructions: info.instructions },
    );
    // The SDK reads the body: a Content-Length over the cap, or a stream past it, gets 413.
    const transport = new web.WebStandardStreamableHTTPServerTransport({
      sessionIdGenerator: undefined,
      enableJsonResponse: true,
      maxRequestBodySize: info.maxBody ?? 2_000_000,
    });

    server.setRequestHandler(types.ListToolsRequestSchema, () => ({
      tools: tools.map(({ name, title, description, hints, input }) => ({
        name,
        title,
        description,
        inputSchema: { ...z.toJSONSchema(input, { io: "input" }), type: "object" as const },
        annotations: { title, ...hints },
      })),
    }));

    server.setRequestHandler(types.CallToolRequestSchema, async ({ params }) => {
      const end = await callTool.run({
        input: { name: params.name, arguments: params.arguments },
      });

      if (end.status === "cancelled") throw end.reason;

      if (end.status === "notDone") {
        return { isError: true, content: [{ type: "text", text: `Not done: ${end.why}` }] };
      }

      const reply = typeof end.value === "string" ? { text: end.value } : end.value;

      return {
        content: [{ type: "text", text: reply.text }],
        ...(reply.data === undefined ? {} : { structuredContent: reply.data }),
      };
    });

    const aborted = Promise.withResolvers<never>();
    const abort = () => aborted.reject(signal.reason);

    signal.addEventListener("abort", abort, { once: true });

    try {
      await server.connect(transport);

      return await Promise.race([transport.handleRequest(input), aborted.promise]);
    } finally {
      signal.removeEventListener("abort", abort);

      await transport.close();
      await server.close();
    }
  },
});

export { handleMcp, mcpRuns } from "./handle.server";
export { mcpServer, mcpTools } from "./tools.server";
export type { McpReply, McpTool } from "./tools.server";

import { resource } from "@tinker/core";

export const sdkServerModule = resource({
  label: "module:@modelcontextprotocol/sdk/server/index.js",
  target: "scope",
  factory: () => import("@modelcontextprotocol/sdk/server/index.js"),
});

export const sdkTransportModule = resource({
  label: "module:@modelcontextprotocol/sdk/server/webStandardStreamableHttp.js",
  target: "scope",
  factory: () => import("@modelcontextprotocol/sdk/server/webStandardStreamableHttp.js"),
});

export const sdkTypesModule = resource({
  label: "module:@modelcontextprotocol/sdk/types.js",
  target: "scope",
  factory: () => import("@modelcontextprotocol/sdk/types.js"),
});

import { tag } from "@tinker/core";
import type { Operation } from "@tinker/core";
import { z } from "zod";

/** A tool's reply, as obelisk's `reply`: plain text, or text with `data` for `structuredContent`. */
export type McpReply = string | { text: string; data?: Record<string, unknown> };

/** The Core operation a tool runs; its own `input` reader is the only parse of the arguments. */
type ToolRun = Operation.Handle<McpReply | Promise<McpReply>, unknown>;

const toolName = /^[a-z][a-z0-9_]{0,63}$/;

const toolRow = z.strictObject({
  name: z.string().regex(toolName, {
    error: (issue) => `Tool name ${JSON.stringify(issue.input)} must match ${toolName}.`,
  }),
  title: z.string(),
  description: z.string(),
  hints: z
    .strictObject({
      readOnlyHint: z.boolean().optional(),
      destructiveHint: z.boolean().optional(),
      idempotentHint: z.boolean().optional(),
      openWorldHint: z.boolean().optional(),
    })
    .optional(),
  input: z.instanceof(z.ZodObject),
  run: z
    .unknown()
    .refine(
      (value): value is ToolRun =>
        typeof value === "object" && value !== null && "label" in value && "run" in value,
      { error: "A tool runs a Core operation." },
    ),
});

/** The listed input is the one its operation parses, so the list cannot drift from the parse. */
const listedRow = toolRow.refine((row) => row.input === row.run.input, {
  path: ["input"],
  error: "A tool's input must be the schema its operation parses (the same object).",
});

export type McpTool = z.output<typeof listedRow>;

/** Only the names, to say which one a list repeats. */
const toolNames = z.array(z.object({ name: z.string() }));

/** What the server tells a client at initialize, and its body cap (default 2_000_000 bytes). */
export const mcpServer = tag({
  label: "mcp.server",
  parse: z.strictObject({
    name: z.string().min(1),
    version: z.string().min(1),
    instructions: z.string().optional(),
    /** The largest request body in bytes; obelisk's `express.json` limit is 2 MB. */
    maxBody: z.number().int().positive().optional(),
  }),
});

/**
 * The tools, as data: each row's zod `input` is both the listed JSON Schema and the one parse of
 * its operation (the same object, checked). Names are unique. Both are checked when the tag is bound.
 */
export const mcpTools = tag({
  label: "mcp.tools",
  parse: z
    .array(listedRow)
    .refine(
      (rows) =>
        rows.every(({ name }, index) => rows.findIndex((row) => row.name === name) === index),
      {
        error: (issue) => {
          const names = toolNames.parse(issue.input).map(({ name }) => name);
          const twice = names.find((name, index) => names.indexOf(name) !== index);

          return `Tool name ${JSON.stringify(twice)} is used twice.`;
        },
      },
    ),
});
